k5_sql:
SELECT T2.Name FROM badges AS T2 WHERE T2.UserId IN (
  SELECT UserId FROM comments GROUP BY UserId HAVING COUNT(Id) = (
    SELECT MAX(cnt) FROM (SELECT COUNT(Id) AS cnt FROM comments GROUP BY UserId)
  )
)

